sys_script_client.script:
function onSubmit() {

    var requestType = g_form.getValue('request_type');
    var facility = g_form.getValue('sports_facility');
    var description = g_form.getValue('description');
    var priority = g_form.getValue('priority');
    var equipment = g_form.getValue('equipment');

    if (!requestType || !facility ||
        !description || !priority) {

        g_form.addErrorMessage(
            'Please provide all mandatory request information.'
        );

        return false;
    }

    if (requestType == 'equipment_issue' && !equipment) {

        g_form.addErrorMessage(
            'Please select equipment for an Equipment Issue request.'
        );

        return false;
    }

    return true;
}
